const long gmtOffset_sec = 19800;
const int daylightOffset_sec = 0;

time_t baseEpoch = 0;
uint64_t baseRtcUs = 0;

bool gotInfo = 0;
WiFiMulti wifiMulti;
bool wifiOn = 0;
void wifiSetup(void *param)
{
    WiFi.mode(WIFI_STA);
    wifiOn = 1;
    for (int i = 0; i < WIFI_COUNT; i++)
    {
        wifiMulti.addAP(
            wifiCreds[i].ssid,
            wifiCreds[i].pass);
    }

    while (wifiMulti.run() != WL_CONNECTED)
    {
        vTaskDelay(pdMS_TO_TICKS(500));
    }

    configTime(gmtOffset_sec, daylightOffset_sec,
               "time.google.com",
               "time.cloudflare.com",
               "pool.ntp.org");

    struct tm timeinfo;
    baseEpoch = 0;
    baseRtcUs = 0;
    while (!getLocalTime(&timeinfo))
    {
        vTaskDelay(pdMS_TO_TICKS(500));
    }

    baseEpoch = time(nullptr);
    baseRtcUs = esp_timer_get_time();

    WiFi.disconnect(true);
    WiFi.mode(WIFI_OFF);
    wifiOn = 0;
    vTaskDelete(NULL);
}

extern int afkTime;
unsigned long lastFrame = 0;
unsigned long frameInterval = 100;
int current_planetFrame = 0;
bool locked = 0;

void syncTimeAsync()
{
    xTaskCreate(
        wifiSetup,
        "WiFi Time",
        4096,
        NULL,
        1,
        NULL);
    gotInfo = 1;
}

void showStats()
{
    if ((!wifiOn && baseEpoch == 0) || !gotInfo)
    {
        syncTimeAsync();
    }

    uint64_t nowUs = esp_timer_get_time();
    time_t now = baseEpoch + (nowUs - baseRtcUs) / 1000000;

    struct tm *t = localtime(&now);
    u8g2.clearBuffer();
    if (millis() - lastFrame >= frameInterval)
    {
        lastFrame = millis();
        current_planetFrame = (current_planetFrame + 2) % planetallArray_LEN;
    }
    u8g2.drawBitmap(71, -19, 64 / 8, 64, planetallArray[current_planetFrame]);
    char timeStr[9];
    strftime(timeStr, sizeof(timeStr), "%I:%M %p", t);
    u8g2.setFont(u8g2_font_6x13O_tr);
    char day[15];
    strftime(day, sizeof(day), "%A,", t);
    u8g2.drawStr(36, 36, day);
    
    // Calender
    u8g2.drawXBMP(3, 3, 30, 38, image_Calender_bits);
    
    // Layer 7
    u8g2.setFont(u8g2_font_profont22_tr);
    char date[3];
    strftime(date, sizeof(date), "%d", t);
    u8g2.drawStr(7, 25, date);
    
    u8g2.setFont(u8g2_font_6x13O_tr);
    char month[5];
    strftime(month, sizeof(month), "%b", t);
    u8g2.drawStr(9, 37, month);
    
    // Layer 8
    char year[5];
    strftime(year, sizeof(year), "%Y", t);
    u8g2.drawStr(36, 22, year);
    
    if (rightButtonTap())
    {
        locked = !locked;
    }
    if (locked)
    {
        // Locked
        u8g2.drawXBMP(113, 50, 7, 8, image_Locked_bits);
        afkTime = 0;
    }
    u8g2.setFont(u8g2_font_profont22_tr);
    int w = u8g2.getStrWidth(timeStr);
    if(wifiOn){
        u8g2.drawXBMP(62,3,15,16,connectingIcon);
    }
    u8g2.drawStr(4, 59, timeStr);
    u8g2.sendBuffer();
}